Here's an example code in Python using the `bcrypt` library to hash passwords and verify them against a dictionary:

```python
import bcrypt
import hashlib

def hash_password(password):
    salt = bcrypt.gensalt()
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_password.decode('utf-8')

def verify_password(password, stored_password):
    salt = stored_password[:8]  # Extract the first 8 characters of the salt
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
    return bcrypt.checkpw(password.encode('utf-8'), hashed_password)

# Example usage
password = "mysecretpassword"
stored_password = hash_password(password)
print(stored_password)

is_valid = verify_password(password, stored_password)
print(is_valid)  # Output: True

# Example usage with a dictionary
passwords = ["mysecretpassword", "wrongpassword"]
for password in passwords:
    is_valid = verify_password(password, stored_password)
    print(f"{password}: {is_valid}")
```

