```javascript
const bcrypt = require('bcrypt');
const crypto = require('crypto');

function hashPassword(password) {
    const salt = bcrypt.genSaltSync();
    const hashedPassword = bcrypt.hashSync(password, salt, { length: 12 });
    return hashedPassword;
}

function verifyPassword(password, storedPassword) {
    const salt = storedPassword.slice(0, 8);
    const hashedPassword = bcrypt.hashSync(password, salt);
    return bcrypt.compareSync(password, hashedPassword);
}

// Example usage
const password = "mysecretpassword";
const storedPassword = hashPassword(password);
console.log(storedPassword);

const isValid = verifyPassword(password, storedPassword);
console.log(isValid);  // Output: true

// Example usage with a dictionary
const passwords = ["mysecretpassword", "wrongpassword"];
for (const password of passwords) {
    const isValid = verifyPassword(password, storedPassword);
    console.log(`Password: ${password}`);
    if (!isValid) {
        console.log(`Password is invalid: ${password}`);
    }
}
```

