{
    public static string HashPassword(string password)
    {
        using var sha256 = SHA256.Create();
        byte[] bytes = sha256.ComputeHash(password);
        return Convert.ToBase64String(bytes);
    }

    public static bool VerifyPassword(string password, string storedPassword)
    {
        using var sha256 = SHA256.Create();
        byte[] bytes = sha256.ComputeHash(password);
        return Convert.FromBase64String(bytes).Equals(Convert.FromBase64String(storedPassword));
    }
}

// Example usage
string password = "mysecretpassword";
string storedPassword = PasswordHasher.HashPassword(password);
Console.WriteLine(storedPassword);

bool isValid = PasswordHasher.VerifyPassword(password, storedPassword);
Console.WriteLine(isValid);  // Output: true

// Example usage with a dictionary
string[] passwords = new string[] { "mysecretpassword", "wrongpassword" };
foreach (string password in passwords)
{
    bool isValid = PasswordHasher.VerifyPassword(password, storedPassword);
    Console.WriteLine($"Password: {password}");
    if (!isValid)
    {
        Console.WriteLine($"Password is invalid: {password}");
    }
}
```

